import { z } from 'zod'
export async function getRoutesByProjectGroupId({
	projectGroupId
}: {
	projectGroupId: string
}) {
	const gqlQuery = {
		query: `query GetRoutesByProjectGroupId($input: ProjectRoutesInput!) {
        getRoutesByProjectGroupId(input: $input) {
          name
          runtime
          path
        }
    }`,
		variables: {
			input: { projectGroupId, routingBehaviors: ['expo-page', 'page'] }
		}
	}
	const response = await fetch(
		`${process.env.EXPO_PUBLIC_CREATE_API_URL}/graphql`,
		{
			headers: {
				'Content-Type': 'application/json'
			},
			method: 'POST',
			body: JSON.stringify(gqlQuery)
		}
	)
	if (!response.ok) {
		throw new Error('Failed to fetch routes')
	}

	const rawData = await response.json()

	const routesSchema = z.object({
		data: z.object({
			getRoutesByProjectGroupId: z.array(
				z.object({
					name: z.string(),
					runtime: z.enum(['EXPO', 'REACT']),
					path: z.string()
				})
			)
		})
	})

	const {
		data: { getRoutesByProjectGroupId }
	} = routesSchema.parse(rawData)
	return getRoutesByProjectGroupId
}
